window.QUIZ = (window.QUIZ || []).concat([
  { id: "2-001", ch: 2, sec: "2.1", page: 11, type: "recall", level: 1,
    q: "Which two measures of soil water does the book call important for managing irrigation systems?",
    opts: ["Bulk density and porosity","Soil water content and soil water potential","Field capacity and saturation","Infiltration rate and permeability"], a: 1,
    why: "Water content tells how much water is in the soil, and water potential tells how hard plants must work to remove it. The other pairs are soil properties or limits, not the two measures of soil water status.",
    eq: null, calc: null, fig: null, table: null },
  { id: "2-002", ch: 2, sec: "2.1", page: 11, type: "concept", level: 1,
    q: "Irrigation management aims to keep soil water between a wet limit and a dry limit. What sets each limit?",
    opts: ["Wet limit: field capacity of sand. Dry limit: field capacity of clay","Wet limit: saturation of the subsoil. Dry limit: oven-dry soil","Wet limit: poor aeration. Dry limit: plants struggle to get water","Wet limit: runoff. Dry limit: soil cracking"], a: 2,
    why: "Plants suffer when soil is so wet that aeration is poor, and when it is so dry that they have difficulty obtaining water. The goal is to stay between those limits.",
    eq: null, calc: null, fig: null, table: null },
  { id: "2-003", ch: 2, sec: "2.2", page: 11, type: "figure", level: 1,
    q: "In Figure 2.1, what fills the pore space of a soil, and what makes up the solid material?",
    opts: ["Pores hold water and organic matter. Solids are mineral matter and air","Pores hold air and water. Solids are mineral matter and organic matter","Pores hold air only. Solids are mineral matter, organic matter and water","Pores hold mineral fines. Solids are sand and gravel"], a: 1,
    why: "The pie chart splits the soil into pore space (air plus water) and solid material (mineral plus organic matter). Organic matter is part of the solids, not the pores.",
    eq: null, calc: null, fig: "2.1", table: null },
  { id: "2-004", ch: 2, sec: "2.2", page: 11, type: "recall", level: 1,
    q: "How is soil porosity defined?",
    opts: ["Volume of water divided by total bulk volume","Volume of solids divided by volume of pores","Volume of pores divided by total bulk volume","Mass of dry soil divided by bulk volume"], a: 2,
    why: "Porosity is the ratio of the pore (void) volume to the total bulk volume. Water volume over bulk volume is volumetric water content, and dry mass over bulk volume is bulk density.",
    eq: null, calc: null, fig: null, table: null },
  { id: "2-005", ch: 2, sec: "2.2", page: 12, type: "recall", level: 1,
    q: "What value of soil particle density does the book give as common for mineral soils?",
    opts: ["1.33 g/cm³","2.65 g/cm³","1.60 g/cm³","1.00 g/cm³"], a: 1,
    why: "Mineral particles (mostly quartz and similar minerals) are about 2.65 g/cm³. 1.00 g/cm³ is water, and 1.33 to 1.60 g/cm³ are typical bulk densities, which include the pore space.",
    eq: "2.2", calc: null, fig: null, table: null },
  { id: "2-006", ch: 2, sec: "2.2", page: 11, type: "calc", level: 1,
    q: "An undisturbed core of 120 cm³ weighs 162 g after oven drying. What is the bulk density?",
    opts: ["1.20 g/cm³","1.62 g/cm³","1.35 g/cm³","0.74 g/cm³"], a: 2,
    why: "ρb = Ms / Vb = 162 g / 120 cm³ = 1.35 g/cm³. 0.74 is the ratio inverted, and the others misread the inputs.",
    eq: "2.1", calc: "eq-2.1", fig: null, table: null },
  { id: "2-007", ch: 2, sec: "2.2", page: 11, type: "calc", level: 2,
    q: "A 200 cm³ soil core weighs 330 g as sampled and 280 g after 24 hours at 105 °C. What is the bulk density?",
    opts: ["0.25 g/cm³","1.65 g/cm³","0.71 g/cm³","1.40 g/cm³"], a: 3,
    why: "Bulk density uses the dry mass: 280 g / 200 cm³ = 1.40 g/cm³. Using the wet mass gives 1.65, which is not bulk density. 0.25 is the volumetric water content (50 cm³ / 200 cm³).",
    eq: "2.1", calc: "eq-2.1", fig: null, table: null },
  { id: "2-008", ch: 2, sec: "2.2", page: 12, type: "calc", level: 1,
    q: "A field soil has a bulk density of 1.48 g/cm³. Using a particle density of 2.65 g/cm³, what is its porosity?",
    opts: ["48%","56%","44%","79%"], a: 2,
    why: "φ = (1 − 1.48 / 2.65) × 100% = (1 − 0.558) × 100% = 44%. 56% forgets to subtract from 1 (that is the solids fraction). 79% comes from inverting the ratio.",
    eq: "2.2", calc: "eq-2.2", fig: null, table: null },
  { id: "2-009", ch: 2, sec: "2.2", page: 12, type: "calc", level: 2,
    q: "An undisturbed sample of 90 cm³ weighs 126 g after drying. What is its porosity (particle density 2.65 g/cm³)?",
    opts: ["53%","60%","47%","35%"], a: 2,
    why: "ρb = 126 / 90 = 1.40 g/cm³. φ = (1 − 1.40 / 2.65) × 100% = 47%. 53% is the solids fraction (1.40 / 2.65). Rounded to the nearest percent.",
    eq: "2.2", calc: "eq-2.2", fig: null, table: null },
  { id: "2-010", ch: 2, sec: "2.2", page: 12, type: "calc", level: 3,
    q: "A compacted layer has a porosity of 38%. With a particle density of 2.65 g/cm³, what is its bulk density?",
    opts: ["1.92 g/cm³","1.64 g/cm³","1.27 g/cm³","1.01 g/cm³"], a: 1,
    why: "Rearrange Eq. 2.2: ρb = ρp (1 − φ) = 2.65 × 0.62 = 1.64 g/cm³. 1.01 multiplies by the porosity instead of the solids fraction (0.38 × 2.65).",
    eq: "2.2", calc: "eq-2.2", fig: null, table: null },
  { id: "2-011", ch: 2, sec: "2.2", page: 12, type: "recall", level: 2,
    q: "What are the USDA size limits for the soil separates?",
    opts: ["Clay < 0.05 mm, silt 0.05 to 0.2 mm, sand 0.2 to 2.0 mm","Clay < 0.002 mm, silt 0.002 to 0.5 mm, sand 0.5 to 5.0 mm","Clay < 0.002 mm, silt 0.002 to 0.05 mm, sand 0.05 to 2.0 mm","Clay < 0.02 mm, silt 0.02 to 0.2 mm, sand 0.2 to 2.0 mm"], a: 2,
    why: "USDA limits are clay below 0.002 mm, silt 0.002 to 0.05 mm, and sand 0.05 to 2.0 mm. Particles larger than 2.0 mm are gravel and are not part of texture.",
    eq: null, calc: null, fig: null, table: null },
  { id: "2-012", ch: 2, sec: "2.2", page: 12, type: "figure", level: 1,
    q: "Using the textural triangle in Figure 2.2, what is the texture of a soil with 65% sand and 10% clay?",
    opts: ["Loam","Loamy sand","Sandy loam","Sandy clay loam"], a: 2,
    why: "At 10% clay, sandy loam runs from about 52% to 80% sand, so 65% sand is sandy loam. Loamy sand needs more than about 80% sand at that clay content, and sandy clay loam needs at least 20% clay.",
    eq: null, calc: null, fig: "2.2", table: null },
  { id: "2-013", ch: 2, sec: "2.2", page: 12, type: "figure", level: 2,
    q: "Using Figure 2.2, what is the texture of a soil with 30% sand, 35% clay and 35% silt?",
    opts: ["Clay","Silty clay loam","Sandy clay loam","Clay loam"], a: 3,
    why: "Clay loam covers 27 to 40% clay with 20 to 45% sand. Silty clay loam requires less than 20% sand, sandy clay loam requires more than 45% sand, and clay requires more than 40% clay.",
    eq: null, calc: null, fig: "2.2", table: null },
  { id: "2-014", ch: 2, sec: "2.3", page: 13, type: "recall", level: 1,
    q: "What drying procedure does the book specify for determining mass water content?",
    opts: ["At least 48 hours at 220 °C","At least 2 hours at 105 °C","At least 24 hours at 60 °C","At least 24 hours at 105 °C"], a: 3,
    why: "Samples are dried for at least 24 hours at 105 °C (220 °F). 220 is the Fahrenheit value, not Celsius. Lower temperatures leave water in the sample.",
    eq: null, calc: null, fig: null, table: null },
  { id: "2-015", ch: 2, sec: "2.3", page: 13, type: "recall", level: 2,
    q: "Mass (gravimetric) water content is the mass of water divided by what?",
    opts: ["The mass of the oven-dry soil","The mass of the soil solids plus organic matter burned off","The mass of the wet soil sample","The bulk volume of the sample"], a: 0,
    why: "θm is on a dry soil basis: Mw / Ms. Dividing by the wet mass is a common error that gives a lower value. Dividing by bulk volume mixes units and is not θm.",
    eq: "2.3", calc: null, fig: null, table: null },
  { id: "2-016", ch: 2, sec: "2.3", page: 13, type: "calc", level: 1,
    q: "A soil sample weighs 150 g wet and 125 g after oven drying. What is its mass water content?",
    opts: ["0.17","0.20","0.83","0.25"], a: 1,
    why: "Mw = 150 − 125 = 25 g. θm = 25 / 125 = 0.20. Dividing by the wet mass gives 0.17, and 0.83 is dry mass over wet mass.",
    eq: "2.3", calc: "eq-2.3", fig: null, table: null },
  { id: "2-017", ch: 2, sec: "2.3", page: 13, type: "calc", level: 2,
    q: "A sample weighs 260 g wet and 220 g oven dry. What is the mass water content as a percent?",
    opts: ["84.6%","18.2%","15.4%","40.0%"], a: 1,
    why: "θm = (260 − 220) / 220 = 40 / 220 = 0.182, or 18.2%. 15.4% divides by the wet mass (40 / 260). 40.0% treats grams of water as a percent.",
    eq: "2.3", calc: "eq-2.3", fig: null, table: null },
  { id: "2-018", ch: 2, sec: "2.3", page: 13, type: "calc", level: 1,
    q: "An undisturbed 250 cm³ core contains 60 cm³ of water. What is its volumetric water content?",
    opts: ["4.17","0.31","0.24","0.42"], a: 2,
    why: "θv = Vw / Vb = 60 / 250 = 0.24 cm³/cm³. 4.17 is the ratio inverted.",
    eq: "2.4", calc: "eq-2.4", fig: null, table: null },
  { id: "2-019", ch: 2, sec: "2.3", page: 13, type: "calc", level: 1,
    q: "A soil has a mass water content of 0.15 and a bulk density of 1.40 g/cm³. What is its volumetric water content?",
    opts: ["0.36","0.11","0.15","0.21"], a: 3,
    why: "θv = θm × ρb / ρw = 0.15 × 1.40 / 1.00 = 0.21. Dividing instead of multiplying gives 0.11. θv is larger than θm whenever bulk density exceeds 1 g/cm³.",
    eq: "2.5", calc: "eq-2.5", fig: null, table: null },
  { id: "2-020", ch: 2, sec: "2.3", page: 14, type: "calc", level: 2,
    q: "A 100 cm³ field core weighs 156 g as sampled and 130 g after oven drying. What is its volumetric water content?",
    opts: ["0.26","0.17","0.31","0.20"], a: 0,
    why: "θm = 26 / 130 = 0.20. ρb = 130 / 100 = 1.30 g/cm³. θv = 0.20 × 1.30 = 0.26. 0.31 uses the wet mass for bulk density (1.56), and 0.20 stops at θm.",
    eq: "2.5", calc: "eq-2.5", fig: null, table: null },
  { id: "2-021", ch: 2, sec: "2.3", page: 13, type: "calc", level: 3,
    q: "A probe reads a volumetric water content of 0.30 in a soil with a bulk density of 1.50 g/cm³. What is the mass water content?",
    opts: ["0.11","0.30","0.20","0.45"], a: 2,
    why: "Rearrange Eq. 2.5: θm = θv × ρw / ρb = 0.30 / 1.50 = 0.20. Multiplying gives 0.45, which goes the wrong direction.",
    eq: "2.5", calc: "eq-2.5", fig: null, table: null },
  { id: "2-022", ch: 2, sec: "2.3", page: 13, type: "calc", level: 1,
    q: "A soil layer 18 inches thick has a volumetric water content of 0.28. What equivalent depth of water does it hold?",
    opts: ["64.3 in","5.04 in","0.42 in","2.80 in"], a: 1,
    why: "d = θv L = 0.28 × 18 in = 5.04 in. 0.42 in uses the thickness in feet (1.5 ft) and reports inches. 64.3 divides instead of multiplying.",
    eq: "2.6", calc: "eq-2.6", fig: null, table: null },
  { id: "2-023", ch: 2, sec: "2.3", page: 14, type: "calc", level: 2,
    q: "The top 2 ft of a field is at a volumetric water content of 0.22. What depth of water must be added to raise it to 0.32?",
    opts: ["7.7 in","0.10 in","2.4 in","1.2 in"], a: 2,
    why: "Current d = 0.22 × 24 = 5.28 in. Target d = 0.32 × 24 = 7.68 in. Add 7.68 − 5.28 = 2.4 in. 1.2 in uses only 1 ft, and 7.7 in is the total target storage, not the amount to add.",
    eq: "2.6", calc: "eq-2.6", fig: null, table: null },
  { id: "2-024", ch: 2, sec: "2.3", page: 13, type: "calc", level: 2,
    q: "The top 30 cm of soil has a volumetric water content of 0.25. How much water does it hold, in millimeters?",
    opts: ["750 mm","120 mm","7.5 mm","75 mm"], a: 3,
    why: "d = θv L = 0.25 × 300 mm = 75 mm (7.5 cm). 7.5 mm is a cm to mm slip.",
    eq: "2.6", calc: "eq-2.6", fig: null, table: null },
  { id: "2-025", ch: 2, sec: "2.3", page: 13, type: "concept", level: 2,
    q: "Mass water content is easier to measure. Why is volumetric water content usually more useful for irrigation?",
    opts: ["It converts directly to a depth of water per depth of soil","It does not depend on the soil's bulk density","It is always larger than the mass water content","It can be measured without any soil sample"], a: 0,
    why: "θv times layer depth gives inches of water (d = θv L), which compares directly with rain, irrigation and ET depths. θv does depend on bulk density, which is why Eq. 2.5 is needed to convert from θm.",
    eq: null, calc: null, fig: null, table: null },
  { id: "2-026", ch: 2, sec: "2.4", page: 14, type: "recall", level: 2,
    q: "What does soil water potential measure?",
    opts: ["The rate at which water enters the soil surface","The energy status of soil water relative to a standard reference","The maximum water a soil can hold after drainage","The volume of water held per volume of soil"], a: 1,
    why: "Soil water potential is the energy status of soil water compared with a reference, expressed per volume (pressure) or per weight (head). The others are water content, infiltration rate and field capacity.",
    eq: null, calc: null, fig: null, table: null },
  { id: "2-027", ch: 2, sec: "2.4", page: 14, type: "concept", level: 2,
    q: "A wet soil may have a matric potential of −0.3 bar and a dry soil −15 bars. Which statement is correct?",
    opts: ["The wet soil water is at higher energy and easier for plants to extract","Both are at the same energy since potentials are negative","The wet soil water is at lower energy because it is closer to zero","The dry soil water is at higher energy because the number is larger"], a: 0,
    why: "The reference is assigned zero at a high energy level, so less negative means higher energy. Water at −0.3 bar is held loosely, while water at −15 bars is held near the wilting point.",
    eq: null, calc: null, fig: null, table: null },
  { id: "2-028", ch: 2, sec: "2.4", page: 15, type: "recall", level: 1,
    q: "Equation 2.7 gives total soil water potential as the sum of which three components?",
    opts: ["Gravitational, pressure and thermal","Matric, osmotic and overburden","Capillary, adsorptive and thermal","Gravitational, matric and osmotic"], a: 3,
    why: "ψt = ψg + ψm + ψo. The book notes that Eq. 2.7 ignores overburden pressure.",
    eq: "2.7", calc: "eq-2.7", fig: null, table: null },
  { id: "2-029", ch: 2, sec: "2.4", page: 15, type: "concept", level: 2,
    q: "What causes matric potential?",
    opts: ["Dissolved salts in the soil water","The weight of the soil above a given depth","Adhesion and surface tension forces between soil particles and water","The pull of gravity on water in large pores"], a: 2,
    why: "Adhesion to particles and surface tension at the soil-air interface produce capillarity, called soil water tension. Salts produce osmotic potential and gravity produces gravitational potential.",
    eq: null, calc: null, fig: null, table: null },
  { id: "2-030", ch: 2, sec: "2.4", page: 15, type: "concept", level: 3,
    q: "How does osmotic potential affect soil water, according to the book?",
    opts: ["It does not affect flow through the profile but does affect plant uptake and evaporation","It affects only tensiometer readings, not plants","It increases evaporation as salts concentrate","It drives water flow down through the profile like gravity"], a: 0,
    why: "Osmotic potential matters where a semipermeable membrane is present, like roots, so it affects uptake. It also lowers evaporation as salts concentrate. It does not influence liquid flow through the soil profile.",
    eq: null, calc: null, fig: null, table: null },
  { id: "2-031", ch: 2, sec: "2.4", page: 15, type: "concept", level: 2,
    q: "When salts are minimal, which component of soil water potential dominates the release of water from soil to plants?",
    opts: ["Gravitational potential","Overburden potential","Osmotic potential","Matric potential"], a: 3,
    why: "With low salinity, osmotic potential is near zero and the matric potential (soil water tension) controls how easily roots can extract water. Gravity mainly affects drainage of large pores.",
    eq: null, calc: null, fig: null, table: null },
  { id: "2-032", ch: 2, sec: "2.4", page: 15, type: "recall", level: 1,
    q: "At what soil water tension is the permanent wilting point traditionally defined?",
    opts: ["1/3 bar (33 cb)","75 cb","15 bars (1,500 cb)","1 bar (100 cb)"], a: 2,
    why: "The working definition of wilting point is 15 bars or 1,500 cb. One-third bar is a common field capacity definition, and 75 cb is the practical upper limit of a tensiometer.",
    eq: null, calc: null, fig: null, table: null },
  { id: "2-033", ch: 2, sec: "2.4", page: 15, type: "concept", level: 2,
    q: "Some plants actually wilt permanently at 20 bars, not 15. Why is the 15-bar wilting point still a reasonable working definition?",
    opts: ["Soil water tension cannot exceed 15 bars","Water between 15 and 20 bars drains out by gravity","All crops wilt at exactly 15 bars","Water content changes only slightly over a wide range of tension near 15 bars"], a: 3,
    why: "The release curve is nearly flat at high tension, so the water content at 20 bars is close to that at 15 bars. The error in available water is small.",
    eq: null, calc: null, fig: null, table: null },
  { id: "2-034", ch: 2, sec: "2.4", page: 16, type: "recall", level: 1,
    q: "Field capacity is often taken as the water content at what matric potential?",
    opts: ["−15 bars (1,500 cb tension)","0 bar (saturation)","−1 bar (100 cb tension)","−1/3 bar (33 cb tension)"], a: 3,
    why: "The common definition is −1/3 bar, or 33 cb of tension. The book cautions that this is not a good definition for all soils.",
    eq: null, calc: null, fig: null, table: null },
  { id: "2-035", ch: 2, sec: "2.4", page: 16, type: "concept", level: 3,
    q: "If you define field capacity of a fine sand as the water content at 33 cb, what error results?",
    opts: ["There is no error, because 33 cb fits all soils","FC equals saturation, because sands do not drain","FC is overestimated, because sands reach FC at a higher tension","FC is underestimated, because sands reach FC at a much lower tension"], a: 3,
    why: "The book says 33 cb is too large a tension for medium and coarse soils. Figure 2.6 shows fine sand at FC near 8 to 10 cb (θ = 0.15). At 33 cb its water content is lower, so FC and AWC would be underestimated.",
    eq: null, calc: null, fig: "2.6", table: null },
  { id: "2-036", ch: 2, sec: "2.4", page: 16, type: "recall", level: 1,
    q: "At saturation, the volumetric water content of a soil equals what?",
    opts: ["Its bulk density","Its field capacity","Its available water capacity","Its porosity"], a: 3,
    why: "At saturation all voids are full of water, so θs = φ. Field capacity is lower because gravity drains the largest pores.",
    eq: null, calc: null, fig: null, table: null },
  { id: "2-037", ch: 2, sec: "2.4", page: 16, type: "concept", level: 1,
    q: "Why is the water content at field capacity always less than at saturation?",
    opts: ["Salts displace water from the pores","Plants remove water until FC is reached","Gravity drains the largest pores and air enters","Evaporation dries the surface to FC"], a: 2,
    why: "After saturation, gravity drains water from the large pores and air replaces it, until drainage becomes negligible at θfc. Plant uptake and evaporation are not part of the definition.",
    eq: null, calc: null, fig: null, table: null },
  { id: "2-038", ch: 2, sec: "2.4", page: 15, type: "table", level: 1,
    q: "From Table 2.1, 1 psi of pressure is equivalent to how many feet of water head?",
    opts: ["2.31 ft","0.433 ft","34 ft","6.89 ft"], a: 0,
    why: "1 psi = 2.31 ft of water. 6.89 is the kPa equivalent of 1 psi, 0.433 is psi per foot, and 34 ft is one atmosphere.",
    eq: null, calc: null, fig: null, table: "2.1" },
  { id: "2-039", ch: 2, sec: "2.4", page: 15, type: "calc", level: 1,
    q: "A pump gauge reads 40 psi. Using Table 2.1, what is the equivalent head of water?",
    opts: ["17.3 ft","275.6 ft","92.4 ft","1,360 ft"], a: 2,
    why: "40 psi × 2.31 ft/psi = 92.4 ft. Dividing by 2.31 gives 17.3, and 275.6 is the pressure in kPa, not head.",
    eq: null, calc: null, fig: null, table: "2.1" },
  { id: "2-040", ch: 2, sec: "2.4", page: 15, type: "calc", level: 3,
    q: "A tensiometer reads 30 cb. Using Table 2.1, what is that tension expressed as a head of water?",
    opts: ["About 69 ft","About 4.4 ft","About 10 ft","About 1.0 ft"], a: 2,
    why: "101.3 cb = 34 ft of water, so 30 cb × 34 / 101.3 = 10.1 ft. Equivalently 30 cb = 30 kPa = 4.35 psi, and 4.35 × 2.31 = 10 ft. 69 ft treats cb as psi, and 4.4 is the value in psi.",
    eq: null, calc: null, fig: null, table: "2.1" },
  { id: "2-041", ch: 2, sec: "2.4", page: 15, type: "table", level: 2,
    q: "From Table 2.1, 1 atmosphere equals 101.3 kPa and 101.3 cb. What is the practical consequence for reading soil water sensors?",
    opts: ["1 cb equals 1 psi, so a 30 cb reading is 30 psi","1 cb equals 1 kPa, so a 30 cb reading is 30 kPa","1 cb equals 1 ft of water, so a 30 cb reading is 30 ft","1 cb equals 1 bar, so a 30 cb reading is 30 bars"], a: 1,
    why: "Since 1 atm is both 101.3 kPa and 101.3 cb, centibars and kilopascals are the same unit size. 100 cb is 1 bar, not 1 cb.",
    eq: null, calc: null, fig: null, table: "2.1" },
  { id: "2-042", ch: 2, sec: "2.4", page: 16, type: "figure", level: 1,
    q: "From Figure 2.6, what is the volumetric water content at field capacity for the fine sandy loam?",
    opts: ["0.34","0.42","0.23","0.10"], a: 2,
    why: "The fine sandy loam curve is marked θfc = 0.23. 0.42 is its saturation value, 0.10 its wilting point, and 0.34 is the silt loam's field capacity.",
    eq: null, calc: null, fig: "2.6", table: null },
  { id: "2-043", ch: 2, sec: "2.4", page: 16, type: "figure", level: 2,
    q: "From Figure 2.6, at about what tension does the silt loam reach field capacity?",
    opts: ["About 20 cb","About 33 cb","About 100 cb","About 8 cb"], a: 0,
    why: "The silt loam θfc marker sits near 20 cb, which the book also cites for tensiometers. About 8 cb is the fine sand's field capacity, and 33 cb is the one-third-bar convention.",
    eq: null, calc: null, fig: "2.6", table: null },
  { id: "2-044", ch: 2, sec: "2.4", page: 16, type: "figure", level: 3,
    q: "From Figure 2.6, which soil has the largest volume of free-draining (gravitational) water, θs − θfc?",
    opts: ["Fine sand, 0.21","Silt loam, 0.19","Silt loam, 0.53","Fine sandy loam, 0.19"], a: 0,
    why: "Fine sand: 0.36 − 0.15 = 0.21. Silt loam: 0.53 − 0.34 = 0.19. Fine sandy loam: 0.42 − 0.23 = 0.19. The silt loam has the highest porosity but drains less of it, and 0.53 is its θs, not drainable water.",
    eq: null, calc: null, fig: "2.6", table: null },
  { id: "2-045", ch: 2, sec: "2.4", page: 16, type: "figure", level: 2,
    q: "Figure 2.7 shows a silt loam with θwp = 0.16. How much water in a 1-ft layer of this soil is unavailable to plants?",
    opts: ["0.16 in","1.92 in","2.16 in","4.08 in"], a: 1,
    why: "Unavailable water lies between 0 and θwp: 0.16 × 12 in = 1.92 in. 2.16 in is the available water ((0.34 − 0.16) × 12), and 4.08 in is the water at FC (0.34 × 12).",
    eq: null, calc: null, fig: "2.7", table: null },
  { id: "2-046", ch: 2, sec: "2.4", page: 16, type: "scenario", level: 2,
    q: "A neighbor tells your grower, 'Field capacity is always the water content at one-third bar.' The grower farms a loamy fine sand. What do you tell him?",
    opts: ["One-third bar is too high a tension for sands, so use field drainage data to set FC","For sands, field capacity equals saturation","For sands, use 15 bars instead","That is correct for every soil"], a: 0,
    why: "The book says 33 cb is fairly good for some fine soils but too large a tension for medium and coarse soils. It recommends estimating FC from actual field conditions, such as sensor readings after drainage.",
    eq: null, calc: null, fig: null, table: null },
  { id: "2-047", ch: 2, sec: "2.4", page: 15, type: "scenario", level: 3,
    q: "A grower switching to a saline well asks why the crop looks stressed even though his θv probe shows the same water content as before. What is the explanation?",
    opts: ["Salts increase the matric potential, making water easier to extract","Salts lower the osmotic potential, so roots work harder to take up water at the same θv","Salinity affects only evaporation, not plants","Salty water raises field capacity, so the probe is wrong"], a: 1,
    why: "Osmotic potential does not change θv or flow in the soil, but it makes plant uptake harder. Where salinity is appreciable, osmotic potential must be considered when judging plant water availability.",
    eq: null, calc: null, fig: null, table: null },
  { id: "2-048", ch: 2, sec: "2.5", page: 17, type: "figure", level: 1,
    q: "In the reservoir analogy of Figure 2.8, what does panel (d), with the plant drawing easily through the large tube, represent?",
    opts: ["Soil water between field capacity and allowable depletion","Soil water between allowable depletion and wilting point","Soil water between saturation and field capacity","Soil water below the permanent wilting point"], a: 0,
    why: "Panel (d) is labeled between field capacity and allowable depletion, where the plant extracts water easily. Panel (e), using the small tube, is below the minimum balance where the plant works harder, and (f) is below wilting.",
    eq: null, calc: null, fig: "2.8", table: null },
  { id: "2-049", ch: 2, sec: "2.5", page: 17, type: "figure", level: 1,
    q: "In Figure 2.8, what does the drain tube on the side of the reservoir represent?",
    opts: ["Gravity drainage of water above field capacity","Water taken up by plant roots","Water held below the wilting point","Water lost to evaporation from the soil surface"], a: 0,
    why: "Water above the drain level leaves by gravity, so after 1 to 3 days the reservoir is at field capacity, the top of the usable reservoir. Plant uptake is shown by the tubes leading to the plant.",
    eq: null, calc: null, fig: "2.8", table: null },
  { id: "2-050", ch: 2, sec: "2.5", page: 16, type: "recall", level: 2,
    q: "In the reservoir analogy, what is allowable depletion (AD)?",
    opts: ["The difference between field capacity and the minimum balance","The difference between field capacity and wilting point","The difference between minimum balance and wilting point","The difference between saturation and field capacity"], a: 0,
    why: "AD is the water a plant can easily extract, from field capacity down to the minimum balance. FC minus WP is the full AWC, and saturation minus FC is gravitational water.",
    eq: null, calc: null, fig: null, table: null },
  { id: "2-051", ch: 2, sec: "2.5", page: 16, type: "concept", level: 2,
    q: "What happens when soil water falls below the minimum balance but is still above the permanent wilting point?",
    opts: ["The plant must work harder for water, and yield potential is reduced","Nothing, since water above wilting point is fully available","Water drains out of the root zone by gravity","The plant cannot take up any water at all"], a: 0,
    why: "Below the minimum balance the plant is stressed and yield potential drops, even though water is still technically available. At wilting point the plant can no longer recover.",
    eq: null, calc: null, fig: null, table: null },
  { id: "2-052", ch: 2, sec: "2.5", page: 17, type: "recall", level: 1,
    q: "How is available water capacity (AWC) defined, and in what units?",
    opts: ["θfc − θv, as total inches in the root zone","θv − θwp, as a fraction of porosity","θfc − θwp, as depth of water per depth of soil (in/in)","θs − θfc, as depth of water per depth of soil (in/in)"], a: 2,
    why: "AWC = θfc − θwp, read as inches of water per inch of soil. θs − θfc is drainable water, θfc − θv is depletion, and θv − θwp is water remaining.",
    eq: "2.8", calc: "eq-2.8", fig: null, table: null },
  { id: "2-053", ch: 2, sec: "2.5", page: 17, type: "calc", level: 1,
    q: "A soil has θfc = 0.27 and θwp = 0.13. What is its available water capacity in inches per foot?",
    opts: ["1.68 in/ft","0.14 in/ft","4.80 in/ft","3.24 in/ft"], a: 0,
    why: "AWC = 0.27 − 0.13 = 0.14 in/in. Times 12 in/ft = 1.68 in/ft. 0.14 forgets the per-foot conversion, and 3.24 uses θfc alone (0.27 × 12).",
    eq: "2.8", calc: "eq-2.8", fig: null, table: null },
  { id: "2-054", ch: 2, sec: "2.5", page: 17, type: "recall", level: 2,
    q: "What does soil water depletion (or deficit), SWD, represent?",
    opts: ["The depth of water that drained below the root zone","The depth of water remaining above the wilting point","The depth of water held at saturation","The depth of water needed to refill the layer to field capacity"], a: 3,
    why: "SWD is how much available water has been removed, (θfc − θv) times depth, so it equals the depth needed to bring the layer back to field capacity. The water above wilting point is the amount remaining.",
    eq: null, calc: null, fig: null, table: null },
  { id: "2-055", ch: 2, sec: "2.5", page: 18, type: "calc", level: 1,
    q: "A silt loam has θfc = 0.30, θwp = 0.12 and a current θv = 0.24. What fraction of the available water has been depleted?",
    opts: ["0.20","0.33","0.80","0.67"], a: 1,
    why: "fd = (θfc − θv) / (θfc − θwp) = 0.06 / 0.18 = 0.33. 0.67 is the fraction remaining. 0.20 divides by θfc instead of AWC.",
    eq: "2.9", calc: "eq-2.9-2.11", fig: null, table: null },
  { id: "2-056", ch: 2, sec: "2.5", page: 18, type: "calc", level: 3,
    q: "The silt loam of Figure 2.6 (θfc = 0.34, θwp = 0.16) now has θv = 0.20. What is the fraction of available water depleted?",
    opts: ["0.59","0.78","0.22","0.41"], a: 1,
    why: "fd = (0.34 − 0.20) / (0.34 − 0.16) = 0.14 / 0.18 = 0.78. 0.22 is fr. 0.41 divides by θfc (0.14 / 0.34), forgetting that water below wilting point is not available.",
    eq: "2.9", calc: "eq-2.9-2.11", fig: null, table: null },
  { id: "2-057", ch: 2, sec: "2.5", page: 18, type: "calc", level: 1,
    q: "A fine sandy loam has θfc = 0.23, θwp = 0.10 and θv = 0.17. What fraction of the available water remains?",
    opts: ["0.54","0.74","0.46","0.41"], a: 0,
    why: "fr = (θv − θwp) / (θfc − θwp) = 0.07 / 0.13 = 0.54. 0.46 is fd. 0.74 is θv / θfc, which ignores the wilting point.",
    eq: "2.10", calc: "eq-2.9-2.11", fig: null, table: null },
  { id: "2-058", ch: 2, sec: "2.5", page: 18, type: "calc", level: 2,
    q: "A 30-inch root zone has an AWC of 0.15 in/in and is 40% depleted. What is the soil water depletion?",
    opts: ["0.06 in","2.7 in","1.8 in","4.5 in"], a: 2,
    why: "SWD = fd × AWC × L = 0.40 × 0.15 × 30 = 1.8 in. 4.5 in is the TAW, and 2.7 in is the water remaining (0.60 fraction).",
    eq: "2.12", calc: "eq-2.12", fig: null, table: null },
  { id: "2-059", ch: 2, sec: "2.5", page: 18, type: "calc", level: 2,
    q: "A soil holds 1.8 inches of available water per foot. The root zone is 3 ft deep and 55% of the available water is depleted. How much water will refill the root zone?",
    opts: ["2.4 in","1.0 in","3.0 in","5.4 in"], a: 2,
    why: "SWD = 0.55 × 1.8 in/ft × 3 ft = 2.97, about 3.0 in. 5.4 in is the full TAW, 2.4 in uses the fraction remaining (0.45), and 1.0 in covers only 1 ft.",
    eq: "2.12", calc: "eq-2.12", fig: null, table: null },
  { id: "2-060", ch: 2, sec: "2.5", page: 18, type: "calc", level: 1,
    q: "A 24-inch layer has θfc = 0.32 and θv = 0.26. What is its soil water depletion?",
    opts: ["0.06 in","7.68 in","6.24 in","1.44 in"], a: 3,
    why: "SWD = (θfc − θv) L = 0.06 × 24 = 1.44 in. 6.24 in is the water stored now (θv L), and 7.68 in is the water at field capacity.",
    eq: "2.13", calc: "eq-2.13", fig: null, table: null },
  { id: "2-061", ch: 2, sec: "2.5", page: 18, type: "calc", level: 3,
    q: "A silty clay loam (θfc = 0.38, θwp = 0.22) is at θv = 0.31 over a 36-inch root zone. How much water must infiltrate to refill it to field capacity?",
    opts: ["11.16 in","2.52 in","3.24 in","5.76 in"], a: 1,
    why: "SWD = (0.38 − 0.31) × 36 = 2.52 in. 3.24 in is the available water remaining (θv − θwp), 5.76 in is the TAW, and 11.16 in is the total water stored.",
    eq: "2.13", calc: "eq-2.13", fig: null, table: null },
  { id: "2-062", ch: 2, sec: "2.5", page: 18, type: "calc", level: 1,
    q: "A loam with AWC = 0.15 in/in has a 36-inch root zone. What is the total available water (TAW)?",
    opts: ["1.8 in","5.4 in","0.45 in","2.7 in"], a: 1,
    why: "TAW = AWC × Rd = 0.15 × 36 = 5.4 in. 0.45 uses the depth in feet, and 2.7 in is half the TAW, a typical allowable depletion, not the TAW itself.",
    eq: "2.14", calc: "eq-2.14", fig: null, table: null },
  { id: "2-063", ch: 2, sec: "2.5", page: 18, type: "calc", level: 2,
    q: "A soil with AWC = 0.12 m/m has a root zone 90 cm deep. What is the TAW?",
    opts: ["75 mm","1.08 mm","10.8 mm","108 mm"], a: 3,
    why: "TAW = 0.12 × 90 cm = 10.8 cm = 108 mm. 10.8 mm leaves the answer in cm but labels it mm.",
    eq: "2.14", calc: "eq-2.14", fig: null, table: null },
  { id: "2-064", ch: 2, sec: "2.5", page: 18, type: "calc", level: 3,
    q: "A root zone has 12 inches of silt loam (AWC 0.18 in/in) over 24 inches of loamy sand (AWC 0.11 in/in). What is the TAW for the 36-inch root zone?",
    opts: ["4.80 in","3.96 in","6.48 in","5.22 in"], a: 0,
    why: "Sum the layers: 0.18 × 12 + 0.11 × 24 = 2.16 + 2.64 = 4.80 in. 6.48 applies the topsoil AWC to the whole depth, and 5.22 averages the two AWCs without weighting by thickness.",
    eq: "2.14", calc: "eq-2.14", fig: null, table: null },
  { id: "2-065", ch: 2, sec: "2.5", page: 18, type: "calc", level: 2,
    q: "The silt loam of Figure 2.6 (θfc = 0.34, θwp = 0.16) is at θv = 0.27 to a depth of 30 inches. What is the soil water depletion?",
    opts: ["3.3 in","8.1 in","2.1 in","5.4 in"], a: 2,
    why: "SWD = (0.34 − 0.27) × 30 = 2.1 in. Equivalently fd = 0.07 / 0.18 = 0.39 and SWD = 0.39 × 0.18 × 30 = 2.1 in. 3.3 in is water remaining, 5.4 in is TAW, and 8.1 in is total water (θv L).",
    eq: "2.13", calc: "eq-2.13", fig: null, table: null },
  { id: "2-066", ch: 2, sec: "2.5", page: 18, type: "calc", level: 3,
    q: "The fine sandy loam of Figure 2.6 (θfc = 0.23, θwp = 0.10) has θv = 0.15 in a 30-inch profile. What is the soil water depletion?",
    opts: ["1.5 in","4.5 in","2.4 in","3.9 in"], a: 2,
    why: "fd = (0.23 − 0.15) / 0.13 = 0.615, and SWD = 0.615 × 0.13 × 30 = 2.4 in, the same as (0.23 − 0.15) × 30. 1.5 in is the water remaining, 3.9 in is the TAW, and 4.5 in is θv L.",
    eq: "2.12", calc: "eq-2.12", fig: null, table: null },
  { id: "2-067", ch: 2, sec: "2.5", page: 18, type: "concept", level: 3,
    q: "Why does SWD = fd × AWC × L (Eq. 2.12) simplify to SWD = (θfc − θv) × L (Eq. 2.13)?",
    opts: ["Because AWC equals θfc for most soils","Because fd equals θfc − θv by definition","Because fd × (θfc − θwp) equals θfc − θv","Because θwp is zero in the root zone"], a: 2,
    why: "fd = (θfc − θv) / (θfc − θwp) and AWC = θfc − θwp, so the AWC cancels and leaves (θfc − θv). Wilting point is not zero, and fd is a fraction, not a water content difference.",
    eq: "2.13", calc: null, fig: null, table: null },
  { id: "2-068", ch: 2, sec: "2.5", page: 18, type: "concept", level: 2,
    q: "When is TAW = AWC × Rd (Eq. 2.14) not adequate, and what should you do instead?",
    opts: ["When the soil is sandy, multiply by porosity instead","When the soil is wet, use θv instead of AWC","When the root zone is deeper than 12 in, use only the top foot","When texture changes with depth, sum AWC × thickness for each layer"], a: 3,
    why: "Eq. 2.14 assumes one texture through the root zone. In layered soils compute the available water of each layer and add them.",
    eq: "2.14", calc: null, fig: null, table: null },
  { id: "2-069", ch: 2, sec: "2.5", page: 16, type: "scenario", level: 1,
    q: "A grower says, 'My beans wilted hard in the drought, then we got an inch of rain and they never came back.' What happened?",
    opts: ["The rain caused surface sealing","The rain was too little to reach field capacity","The beans were below the minimum balance, which always kills plants","The soil reached the permanent wilting point, beyond which plants do not recover"], a: 3,
    why: "At and beyond the permanent wilting point, plants wilt permanently and do not recover even when water is added. Below the minimum balance, plants are stressed but recover.",
    eq: null, calc: null, fig: null, table: null },
  { id: "2-070", ch: 2, sec: "2.5", page: 18, type: "scenario", level: 2,
    q: "A grower's probe shows θv = 0.22 through a 3-ft root zone where field capacity is 0.32. He asks, 'How much can I put on without pushing water below 3 feet?'",
    opts: ["About 3.6 in","About 7.9 in","About 11.5 in","About 1.2 in"], a: 0,
    why: "SWD = (0.32 − 0.22) × 36 in = 3.6 in, the most the root zone can store. 1.2 in fills only 1 ft, and 11.5 in is the water at field capacity (0.32 × 36).",
    eq: "2.13", calc: "eq-2.13", fig: null, table: null },
  { id: "2-071", ch: 2, sec: "2.6", page: 19, type: "calc", level: 2,
    q: "A soil survey lists field capacity as 0.36 in/in and AWC as 0.17 in/in. What is the wilting point?",
    opts: ["0.17 in/in","0.53 in/in","0.47 in/in","0.19 in/in"], a: 3,
    why: "θwp = θfc − AWC = 0.36 − 0.17 = 0.19 in/in. 0.53 adds instead of subtracting.",
    eq: "2.8", calc: "eq-2.8", fig: null, table: null },
  { id: "2-072", ch: 2, sec: "2.6", page: 18, type: "recall", level: 2,
    q: "Which field procedure does the book describe for measuring field capacity?",
    opts: ["Saturate a core in the lab and weigh it immediately","Sample right after a heavy rain while water is ponded","Sample an area where plants have permanently wilted","Flood a small area, cover it, let it drain several days, then sample"], a: 3,
    why: "Flooding, covering to stop evaporation, and sampling once drainage becomes negligible gives θfc through the profile. Sampling while ponded measures near saturation, and a wilted area gives the wilting point.",
    eq: null, calc: null, fig: null, table: null },
  { id: "2-073", ch: 2, sec: "2.6", page: 18, type: "recall", level: 2,
    q: "As a rule of thumb, how long after flooding should you wait before sampling for field capacity?",
    opts: ["Sandy soils 1 day, silt loams 2 days, silty clay loams 3 days","Sandy soils 3 days, silt loams 2 days, silty clay loams 1 day","All soils 12 hours","All soils 7 days"], a: 0,
    why: "Coarse soils drain fastest, so 1 day for sand, 2 for silt loam and 3 for silty clay loam. Reversing the order is the common mistake.",
    eq: null, calc: null, fig: null, table: null },
  { id: "2-074", ch: 2, sec: "2.6", page: 19, type: "concept", level: 2,
    q: "How can the wilting point be found in the field?",
    opts: ["Measure θv at the soil surface on a hot afternoon","Sample θv where available soil water has been exhausted by severe stress","Sample θv one day after a thorough irrigation","Read θv at 33 cb on a tensiometer"], a: 1,
    why: "Where plants have used all available water, the measured θv approximates θwp through the profile. One day after irrigation gives near field capacity.",
    eq: null, calc: null, fig: null, table: null },
  { id: "2-075", ch: 2, sec: "2.6", page: 19, type: "concept", level: 3,
    q: "Irrigation managers usually use one θwp for the whole root zone and a root depth shallower than roots actually explore. Why does this work?",
    opts: ["Deeper roots do not take up any water","It makes TAW larger, so irrigations can be less frequent","Wilting point is truly constant with depth in all soils","It builds in a safety margin and offsets a higher wilting point near the surface"], a: 3,
    why: "Using a shallower root zone underestimates TAW, which is conservative, and it partly accounts for the fact that WP in the upper root zone is often higher than in the lower portion. It simplifies the water balance and has worked well.",
    eq: null, calc: null, fig: null, table: null },
  { id: "2-076", ch: 2, sec: "2.6", page: 18, type: "scenario", level: 2,
    q: "A grower asks how to find the real field capacity of his silt loam without a lab. What is the simplest field method from the book?",
    opts: ["Sample at intervals after a thorough irrigation in a fallow field until θv stops changing","Take one sample on the day of a heavy rain","Multiply the porosity by one-third","Use the θv measured after the crop has wilted"], a: 0,
    why: "When θv stays nearly constant after a thorough wetting, that is θfc. For a silt loam, expect about 2 days of drainage. Samples during rain show near saturation.",
    eq: null, calc: null, fig: null, table: null },
  { id: "2-077", ch: 2, sec: "2.7", page: 19, type: "table", level: 2,
    q: "From Table 2.2, which soil layer has the lowest minimum permeability?",
    opts: ["Gothenburg, 0 to 4 in, 2.0 to 6.0 in/hr","Hobbs, 0 to 8 in, 0.6 to 2.0 in/hr","Geary, 11 to 34 in, 0.2 to 2.0 in/hr","Valentine, 0 to 11 in, 6 to 20 in/hr"], a: 2,
    why: "The Geary silty clay loam/clay loam subsoil from 11 to 34 in has a permeability range starting at 0.2 in/hr, the lowest in the table. It would restrict drainage more than the other layers.",
    eq: null, calc: null, fig: null, table: "2.2" },
  { id: "2-078", ch: 2, sec: "2.7", page: 19, type: "table", level: 3,
    q: "Table 2.2 lists Valentine fine sand with a bulk density of 1.70 to 1.90 g/cm³. Using the midpoint and a particle density of 2.65 g/cm³, what is its porosity?",
    opts: ["About 32%","About 36%","About 68%","About 47%"], a: 0,
    why: "Midpoint ρb = 1.80. φ = (1 − 1.80 / 2.65) × 100% = 32%. 68% is the solids fraction. Sands have lower total porosity than silt loams even though their pores are larger.",
    eq: "2.2", calc: "eq-2.2", fig: null, table: "2.2" },
  { id: "2-079", ch: 2, sec: "2.7", page: 19, type: "table", level: 2,
    q: "According to Table 2.2, which layers have bulk densities of 1.70 to 1.90 g/cm³?",
    opts: ["Boel and Inavale at all depths","Geary and Hobbs at all depths","The surface layers of every soil listed","Valentine at all depths and the Gothenburg sand and gravel below 4 in"], a: 3,
    why: "Valentine (0 to 60 in) and Gothenburg below 4 in are listed at 1.70 to 1.90. Geary and Hobbs are 1.20 to 1.50, and Boel and Inavale are 1.50 to 1.70.",
    eq: null, calc: null, fig: null, table: "2.2" },
  { id: "2-080", ch: 2, sec: "2.7", page: 20, type: "table", level: 1,
    q: "In Table 2.3, which soil texture has the highest available water capacity?",
    opts: ["Clay, 0.12","Silty clay loam, 0.16","Clay loam, 0.15","Silt loam, 0.18"], a: 3,
    why: "Silt loam has AWC = 0.30 − 0.12 = 0.18 in/in. Clays have higher field capacity (0.40) but also high wilting points, so less of their water is available.",
    eq: null, calc: "tab-2.3", fig: null, table: "2.3" },
  { id: "2-081", ch: 2, sec: "2.7", page: 20, type: "table", level: 2,
    q: "Table 2.3 gives clay a field capacity of 0.40, the same as clay loam and silty clay, yet its AWC is only 0.12. Why?",
    opts: ["Clay has the lowest porosity of all textures","Its wilting point is high, 0.28, so much water is held too tightly","Its field capacity is really lower than the table shows","Clay drains below field capacity within one day"], a: 1,
    why: "AWC = 0.40 − 0.28 = 0.12. Clay holds a lot of water, but much of it is held at tensions above 15 bars, where plants cannot extract it.",
    eq: null, calc: "tab-2.3", fig: null, table: "2.3" },
  { id: "2-082", ch: 2, sec: "2.7", page: 20, type: "table", level: 2,
    q: "Using Table 2.3, what is the TAW of a sandy loam with a 2-ft root zone?",
    opts: ["0.24 in","4.80 in","2.88 in","1.92 in"], a: 2,
    why: "Sandy loam AWC = 0.12 in/in. TAW = 0.12 × 24 in = 2.88 in. 4.80 in uses θfc (0.20 × 24), and 0.24 uses 2 instead of 24 inches.",
    eq: "2.14", calc: "tab-2.3", fig: null, table: "2.3" },
  { id: "2-083", ch: 2, sec: "2.7", page: 20, type: "calc", level: 3,
    q: "Using Table 2.3, a silt loam field has a 4-ft root zone. If the crop can tolerate 50% depletion, how much water can be used between irrigations?",
    opts: ["2.16 in","7.20 in","8.64 in","4.32 in"], a: 3,
    why: "TAW = 0.18 × 48 in = 8.64 in, and 50% of it is 4.32 in. 8.64 in is the full TAW, 7.20 in uses θfc (0.30 × 48 × 0.5), and 2.16 in uses only 2 ft.",
    eq: "2.14", calc: "tab-2.3", fig: null, table: "2.3" },
  { id: "2-084", ch: 2, sec: "2.7", page: 20, type: "table", level: 3,
    q: "Comparing silty clay loam and silt loam in Table 2.3, which statement is correct?",
    opts: ["Silty clay loam holds more water at FC but has less available water","Silty clay loam holds less water at FC and less available water","Silt loam holds more water at FC and more available water","Both have the same AWC because both contain silt"], a: 0,
    why: "Silty clay loam: θfc 0.38, AWC 0.16. Silt loam: θfc 0.30, AWC 0.18. The extra clay raises the wilting point (0.22 vs 0.12) more than it raises field capacity.",
    eq: null, calc: null, fig: null, table: "2.3" },
  { id: "2-085", ch: 2, sec: "2.7", page: 20, type: "scenario", level: 1,
    q: "A grower on sand asks why he has to irrigate every 3 days when his neighbor on silt loam goes a week. What is the main reason?",
    opts: ["Sand has a much smaller available water reservoir (AWC 0.08 vs 0.18 in/in)","Silt loam drains to field capacity faster","Sand has a lower infiltration rate","Sand has a higher wilting point than silt loam"], a: 0,
    why: "Table 2.3 gives sand AWC = 0.08 and silt loam 0.18 in/in, so sand stores less than half as much usable water per foot of root zone. Sand actually infiltrates faster and has a lower wilting point.",
    eq: null, calc: null, fig: null, table: "2.3" },
  { id: "2-086", ch: 2, sec: "2.8", page: 20, type: "concept", level: 2,
    q: "Which two forces drive infiltration, and which dominates early in an irrigation?",
    opts: ["Osmosis and gravity, with osmosis dominating early","Capillarity and gravity, with capillarity dominating early","Capillarity and gravity, with gravity dominating early","Adsorption and evaporation, with adsorption dominating early"], a: 1,
    why: "Early on, capillary forces pull water into dry soil equally in all directions. As the soil wets, capillary forces diminish and gravity becomes dominant.",
    eq: null, calc: null, fig: null, table: null },
  { id: "2-087", ch: 2, sec: "2.8", page: 20, type: "figure", level: 2,
    q: "Figure 2.9 shows the wetted zone under a furrow early and late in an irrigation. Why does it change from nearly semicircular to elongated downward?",
    opts: ["The furrow stream erodes the soil bottom","Surface sealing stops lateral flow early in the event","Capillary forces grow stronger with depth","Gravity takes over from capillary forces as time goes on"], a: 3,
    why: "Capillarity acts equally in all directions, so the early wetted shape is about semicircular. Later gravity dominates and pulls the front mainly downward.",
    eq: null, calc: null, fig: "2.9", table: null },
  { id: "2-088", ch: 2, sec: "2.8", page: 20, type: "concept", level: 2,
    q: "If water stays ponded on the soil for a very long time, does the infiltration rate eventually reach zero?",
    opts: ["Yes, once the root zone reaches field capacity","No, it rises again as the soil swells","No, it approaches a steady rate greater than zero","Yes, once the soil is saturated to the water table"], a: 2,
    why: "The rate declines to a steady (basic) infiltration rate. It could only be zero for an impermeable soil or with no gravity. A full root zone still passes water downward.",
    eq: null, calc: null, fig: null, table: null },
  { id: "2-089", ch: 2, sec: "2.8", page: 20, type: "figure", level: 1,
    q: "In Figure 2.10, which soil has the highest steady-state (basic) infiltration rate?",
    opts: ["Fine sand","Fine sandy loam","All three reach the same steady rate","Silt loam"], a: 0,
    why: "The fine sand curve levels off highest, then fine sandy loam, then silt loam. Coarser soils generally have higher infiltration rates.",
    eq: null, calc: null, fig: "2.10", table: null },
  { id: "2-090", ch: 2, sec: "2.8", page: 21, type: "figure", level: 1,
    q: "In Figure 2.11, what does the slope of a cumulative infiltration curve approach late in the event?",
    opts: ["The steady-state infiltration rate","The field capacity of the soil","Zero","The initial infiltration rate"], a: 0,
    why: "The slope of cumulative depth versus time is the infiltration rate, which approaches the steady-state rate of Figure 2.10. Cumulative infiltration keeps rising, so the slope does not go to zero.",
    eq: null, calc: null, fig: "2.11", table: null },
  { id: "2-091", ch: 2, sec: "2.8", page: 21, type: "concept", level: 3,
    q: "After a set, a grower's records show 3 inches of cumulative infiltration. Does that mean water reached 3 inches deep?",
    opts: ["Yes, cumulative infiltration equals the wetting front depth","No, it is a depth of water per land area, like a rain gauge, and it wets far deeper","Yes, but only in sandy soils","No, it means water reached 3 feet deep"], a: 1,
    why: "Cumulative infiltration is volume per unit area, like the depth in a rain gauge. How deep it penetrates depends on the soil water deficit: 3 in into a soil 0.10 below FC wets about 30 in.",
    eq: null, calc: null, fig: null, table: null },
  { id: "2-092", ch: 2, sec: "2.8", page: 21, type: "figure", level: 1,
    q: "In Figure 2.12, for a stationary sprinkler with a constant application rate, what does the shaded area after surface ponding represent?",
    opts: ["Evaporation from the canopy","Deep percolation","Water stored in the root zone","Potential runoff"], a: 3,
    why: "Once the infiltration rate drops below the constant application rate, the difference is water not infiltrated, labeled potential runoff. Runoff begins after surface depressions fill.",
    eq: null, calc: null, fig: "2.12", table: null },
  { id: "2-093", ch: 2, sec: "2.8", page: 22, type: "recall", level: 2,
    q: "What is soil permeability, and when would the steady infiltration rate equal it?",
    opts: ["The initial infiltration rate, equal if the soil is dry","The rate of capillary rise, equal if the water table is shallow","The ability to transmit water when saturated, equal if the soil is uniform and unsealed","The water held at field capacity, equal if the soil is sandy"], a: 2,
    why: "Permeability, or saturated hydraulic conductivity, measures water transmission while saturated. In theory, with a uniform profile and no surface seal, the steady infiltration rate equals it.",
    eq: null, calc: null, fig: null, table: null },
  { id: "2-094", ch: 2, sec: "2.8", page: 22, type: "concept", level: 3,
    q: "Soil surveys list permeability ranges (Table 2.2), but measured steady infiltration in the field is usually lower. Why?",
    opts: ["Surface sealing, layering and other field conditions reduce it below permeability","Soil surveys report infiltration of dry soil only","Field infiltration is always measured during freezing weather","Permeability is measured with salty water"], a: 0,
    why: "Permeability assumes ideal saturated, uniform conditions. In the field, surface seals, layers and other factors reduce the steady infiltration rate significantly below the listed permeability.",
    eq: null, calc: null, fig: null, table: null },
  { id: "2-095", ch: 2, sec: "2.8", page: 22, type: "table", level: 1,
    q: "From Table 2.4, what is the basic infiltration rate of a fine sandy loam with some surface sealing?",
    opts: ["0.25 to 0.50 in/hr","0.35 to 0.50 in/hr","0.13 to 0.28 in/hr","0.15 to 0.30 in/hr"], a: 3,
    why: "Fine sandy loam with some sealing is 0.15 to 0.30 in/hr. 0.35 to 0.50 is the minimal sealing value, 0.13 to 0.28 is silt loam, and 0.25 to 0.50 is fine sand with sealing.",
    eq: null, calc: null, fig: null, table: "2.4" },
  { id: "2-096", ch: 2, sec: "2.8", page: 22, type: "table", level: 3,
    q: "Using Table 2.4 for minimal surface sealing, which soil could take a stationary sprinkler applying 0.60 in/hr without exceeding its full basic infiltration range?",
    opts: ["Fine sand","Fine sandy loam","Coarse sand","Silt loam"], a: 2,
    why: "Coarse sand is 0.75 to 1.00 in/hr, all above 0.60. Fine sand's range is 0.50 to 0.75, so 0.60 is within its range and may exceed it. Finer soils are well below 0.60.",
    eq: null, calc: null, fig: null, table: "2.4" },
  { id: "2-097", ch: 2, sec: "2.8", page: 22, type: "concept", level: 2,
    q: "Why is the infiltration rate per unit land area generally higher under border and basin irrigation than under furrow irrigation?",
    opts: ["Borders always use more water per hour","The whole surface is wetted rather than only the furrows","Basins are built only on sandy soils","Furrows have a higher surface seal from sprinkler drops"], a: 1,
    why: "Infiltration is higher when the entire surface is in contact with water. In furrows only part of the surface is wetted.",
    eq: null, calc: null, fig: null, table: null },
  { id: "2-098", ch: 2, sec: "2.8", page: 22, type: "concept", level: 2,
    q: "How does surface sealing form under sprinkler irrigation compared with surface irrigation?",
    opts: ["Sprinklers: drop impact breaks aggregates. Surface: flowing water shears them","Both: salts cement the surface particles","Both: soil cracking closes the pores","Sprinklers: flowing water shears aggregates. Surface: drop impact breaks them"], a: 0,
    why: "Falling drops break exposed aggregates under sprinklers and rain, while the shearing of flowing water breaks them under surface irrigation. Either way, fine particles form a thin, low-permeability layer.",
    eq: null, calc: null, fig: null, table: null },
  { id: "2-099", ch: 2, sec: "2.8", page: 23, type: "concept", level: 2,
    q: "How does initial soil water content affect infiltration?",
    opts: ["Initial water content has no effect on infiltration","A dry soil has a higher steady rate than a moist soil","A moist soil starts lower but both converge to the same steady rate","A moist soil starts higher and stays higher"], a: 2,
    why: "The wetter the soil, the lower the initial infiltration rate. Over time a moist and a dry soil of the same type converge to the same steady-state rate.",
    eq: null, calc: null, fig: null, table: null },
  { id: "2-100", ch: 2, sec: "2.8", page: 23, type: "scenario", level: 2,
    q: "A furrow irrigator says, 'Water got almost to the end by mid-morning, then the front backed up the field in the hot afternoon. Must be evaporation.' What is the better explanation?",
    opts: ["The soil cracked as it dried in the afternoon","Surface sealing increased as the day warmed","Evaporation from the furrow surface took the water","Warmer water is less viscous, so infiltration rose and the stream shrank"], a: 3,
    why: "Cool groundwater warms as it moves down the field. Higher temperature lowers viscosity and raises infiltration. The book says this recession is often wrongly blamed on evaporation.",
    eq: null, calc: null, fig: null, table: null },
  { id: "2-101", ch: 2, sec: "2.8", page: 22, type: "scenario", level: 2,
    q: "A grower says, 'My first irrigation soaked in fine, but now every set runs off.' The field is clean-tilled under sprinklers. What is the likely cause and remedy?",
    opts: ["Surface sealing from drop impact, so leave residue on the surface or till to restore infiltration","Deep percolation is filling the subsoil, so irrigate more often","Salts are blocking the pores, so add more fertilizer","The soil is at field capacity, so stop irrigating for the season"], a: 0,
    why: "Infiltration often drops after the first irrigation because drops break bare aggregates into a seal. Crop residue protects the surface, and tillage can restore infiltration.",
    eq: null, calc: null, fig: null, table: null },
  { id: "2-102", ch: 2, sec: "2.8", page: 23, type: "scenario", level: 2,
    q: "A grower on a heavy clay says, 'At the start of a set the field drinks water like crazy, then it nearly stops.' What explains this?",
    opts: ["The water is too cold at the start of the set","Shrinkage cracks take water at first, then close as the clay swells","Gravity dominates early and capillarity later","The clay has a very high steady infiltration rate"], a: 1,
    why: "Clays shrink and crack as they dry. Water flows freely into the cracks, then the clay swells and the cracks close, so infiltration drops rapidly. Capillarity dominates early, not gravity.",
    eq: null, calc: null, fig: null, table: null },
  { id: "2-103", ch: 2, sec: "2.8", page: 22, type: "scenario", level: 3,
    q: "A grower says, 'My pivot is fine near the center, but out by the end tower water puddles and runs down the rows.' On his silt loam, what is happening?",
    opts: ["The soil at the outer end has a higher field capacity","The end of the pivot moves too slowly to apply enough water","The peak application rate under the outer spans exceeds the soil's infiltration rate","The outer spans apply less water than the inner spans"], a: 2,
    why: "Outer spans cover more area per revolution and so apply water at a higher peak rate. When that rate exceeds the soil's infiltration rate (Figure 2.13), the difference ponds and runs off.",
    eq: null, calc: null, fig: "2.13", table: null },
  { id: "2-104", ch: 2, sec: "2.8", page: 22, type: "scenario", level: 2,
    q: "A grower plans a solid-set system applying 0.45 in/hr on a fine sandy loam that crusts. Using Table 2.4, what do you tell him?",
    opts: ["Expect runoff, since crusted fine sandy loam takes only 0.15 to 0.30 in/hr","It is fine, since sprinklers never cause runoff","It is fine, since fine sandy loam takes 0.35 to 0.50 in/hr","Expect runoff only if the soil is at wilting point"], a: 0,
    why: "With some surface sealing, fine sandy loam has a basic rate of 0.15 to 0.30 in/hr, below 0.45. The 0.35 to 0.50 range applies only with minimal sealing. Ideally the application rate should not exceed the steady infiltration rate.",
    eq: null, calc: null, fig: null, table: "2.4" },
  { id: "2-105", ch: 2, sec: "2.8", page: 20, type: "scenario", level: 3,
    q: "A salesman tells your grower that a wetting agent, which lowers the surface tension of water, will make water soak in faster on his loam. How should you respond?",
    opts: ["It will always double infiltration, because water flows more easily","Lower surface tension weakens capillary pull, so it may not speed infiltration in a normal soil","It will raise field capacity, so less irrigation is needed","It works only by increasing gravity flow"], a: 1,
    why: "Capillarity, which depends on surface tension, drives early infiltration. Reducing surface tension reduces capillary forces, so in a normally wettable soil infiltration may not improve. Ask for local trial data before buying.",
    eq: null, calc: null, fig: null, table: null },
  { id: "2-106", ch: 2, sec: "2.9", page: 23, type: "figure", level: 1,
    q: "In the simplified storage model of Figure 2.14, where does water in excess of field capacity in the top layer go?",
    opts: ["It drains to the layer immediately below","It evaporates within a day","It is held in the top layer above field capacity","It runs off the surface"], a: 0,
    why: "Each layer is assumed to fill to field capacity, and the excess drains to the next layer. This continues until all water is stored or reaches groundwater.",
    eq: null, calc: null, fig: "2.14", table: null },
  { id: "2-107", ch: 2, sec: "2.9", page: 23, type: "recall", level: 1,
    q: "What is water that penetrates below the root zone called, and what process moves chemicals with it?",
    opts: ["Redistribution, which causes capillary rise","Deep percolation, which causes leaching","Runoff, which causes erosion","Return flow, which causes salination"], a: 1,
    why: "Water moving below the root zone is deep percolation, and the chemicals it carries are leached. Leaching is usually unwanted but is sometimes needed to remove salts (Chapter 7).",
    eq: null, calc: null, fig: null, table: null },
  { id: "2-108", ch: 2, sec: "2.9", page: 24, type: "calc", level: 2,
    q: "A uniform soil has θfc = 0.30 and θv = 0.20. About how deep will 2.0 inches of infiltrated water penetrate?",
    opts: ["0.2 in","20 in","6.7 in","10 in"], a: 1,
    why: "Each inch of soil can take 0.30 − 0.20 = 0.10 in of water. Depth = 2.0 / 0.10 = 20 in. 6.7 in divides by θfc, and 10 in divides by θv.",
    eq: "2.13", calc: "wetting-depth", fig: null, table: null },
  { id: "2-109", ch: 2, sec: "2.9", page: 24, type: "calc", level: 3,
    q: "A profile has 0 to 12 in with θfc = 0.25 and θv = 0.15, and 12 to 36 in with θfc = 0.30 and θv = 0.22. How much water is needed to bring the top 36 inches to field capacity?",
    opts: ["3.60 in","3.12 in","1.20 in","2.88 in"], a: 1,
    why: "Layer 1: 0.10 × 12 = 1.20 in. Layer 2: 0.08 × 24 = 1.92 in. Total = 3.12 in. Using one deficit for the whole depth (0.10 × 36 or 0.08 × 36) gives 3.60 or 2.88 in, and 1.20 in fills only the top layer.",
    eq: "2.13", calc: "eq-2.13", fig: null, table: null },
  { id: "2-110", ch: 2, sec: "2.9", page: 24, type: "calc", level: 3,
    q: "A profile has three layers: 0 to 12 in (θfc 0.30, θv 0.18), 12 to 24 in (θfc 0.32, θv 0.24), and below 24 in (θfc 0.28, θv 0.20). How deep will 3.0 inches of infiltrated water penetrate?",
    opts: ["24.0 in","37.5 in","31.5 in","25.0 in"], a: 2,
    why: "Layer 1 takes 0.12 × 12 = 1.44 in, and layer 2 takes 0.08 × 12 = 0.96 in, total 2.40 in. The remaining 0.60 in wets 0.60 / 0.08 = 7.5 in of layer 3. Depth = 24 + 7.5 = 31.5 in. 25.0 in uses only the top-layer deficit for all 3 in.",
    eq: "2.13", calc: "wetting-depth", fig: null, table: null },
  { id: "2-111", ch: 2, sec: "2.9", page: 24, type: "scenario", level: 3,
    q: "A grower on a sandy loam (Table 2.3, AWC 0.12 in/in) with a 2-ft root zone irrigates when 50% is depleted and always applies 2.0 inches net. How much goes below the roots each time?",
    opts: ["About 0 in","About 0.56 in","About 1.04 in","About 1.44 in"], a: 1,
    why: "TAW = 0.12 × 24 = 2.88 in. SWD at 50% = 1.44 in. Excess = 2.0 − 1.44 = 0.56 in of deep percolation per irrigation. 1.44 in is the amount that should be applied.",
    eq: "2.12", calc: "eq-2.12", fig: null, table: "2.3" },
  { id: "2-112", ch: 2, sec: "2.10", page: 27, type: "figure", level: 3,
    q: "A tensiometer in fine sand reads 75 cb, the top of its practical range. Using Figure 2.6, about what fraction of the available water has been depleted?",
    opts: ["About 45%","About 70%","About 25%","About 95%"], a: 1,
    why: "The book uses Figure 2.6 to show about 70% of AWC is depleted in fine sand at 75 cb, but only about 45% in silt loam. So in sands the tensiometer covers the usual 50% trigger, while in finer soils it may not.",
    eq: null, calc: null, fig: "2.6", table: null },
  { id: "2-113", ch: 2, sec: "2.10", page: 24, type: "calc", level: 3,
    q: "A soil has 0 to 18 in with θfc 0.25 and θv 0.15, and below 18 in θfc 0.20 and θv 0.12. If 3.0 inches infiltrate and the root zone is 30 inches deep, how much water is lost to deep percolation?",
    opts: ["0.36 in","0.24 in","3.0 in","1.2 in"], a: 1,
    why: "Layer 1 takes 0.10 × 18 = 1.8 in. The remaining 1.2 in wets 1.2 / 0.08 = 15 in of layer 2, to a depth of 33 in. The 3 in below the root zone hold 3 × 0.08 = 0.24 in. 3.0 in is the depth penetrated beyond the root zone, not water, and 0.36 uses θv instead of the deficit.",
    eq: "2.13", calc: "wetting-depth", fig: null, table: null },
  { id: "2-114", ch: 2, sec: "2.10", page: 25, type: "recall", level: 1,
    q: "Why does the book call the gravimetric method the standard for measuring soil water content?",
    opts: ["It measures soil water tension directly","It gives results instantly in the field","It is used to verify or calibrate other methods","It is the method most used by irrigators day to day"], a: 2,
    why: "Gravimetric sampling is the reference used to check and calibrate sensors. Because of its labor and delay it is not used regularly for scheduling.",
    eq: null, calc: null, fig: null, table: null },
  { id: "2-115", ch: 2, sec: "2.10", page: 25, type: "calc", level: 3,
    q: "A sample weighs 230 g wet and 200 g oven dry. The soil has ρb = 1.30 g/cm³, θfc = 0.32 and θwp = 0.12. What fraction of the available water remains?",
    opts: ["0.61","0.38","0.15","0.62"], a: 1,
    why: "θm = 30 / 200 = 0.15. θv = 0.15 × 1.30 = 0.195. fr = (0.195 − 0.12) / (0.32 − 0.12) = 0.075 / 0.20 = 0.38 (rounded). 0.62 is fd, 0.15 uses θm instead of θv, and 0.61 is θv / θfc.",
    eq: "2.10", calc: "eq-2.9-2.11", fig: null, table: null },
  { id: "2-116", ch: 2, sec: "2.10", page: 25, type: "table", level: 2,
    q: "Using Table 2.5, a sandy loam sample forms a weak ball that breaks easily and will not slick. About what fraction of available water remains?",
    opts: ["1.0","0.75","0.25","0.50"], a: 1,
    why: "For sandy loam, 'forms weak ball, breaks easily, will not slick' is the 0.75 row. At 0.50 it tends to ball under pressure but seldom holds together, and at field capacity it leaves a wet outline.",
    eq: null, calc: null, fig: null, table: "2.5" },
  { id: "2-117", ch: 2, sec: "2.10", page: 25, type: "table", level: 2,
    q: "Using Table 2.5, a clay loam forms a ball and ribbons out between thumb and forefinger, but does not have a slick feeling. About what fraction of available water remains?",
    opts: ["0.25","0.50","0.75","0"], a: 1,
    why: "Clay loam at 0.50 forms a ball and ribbons out. At 0.75 it easily ribbons out with a slick feeling, and at 0.25 it is only somewhat pliable.",
    eq: null, calc: null, fig: null, table: "2.5" },
  { id: "2-118", ch: 2, sec: "2.10", page: 25, type: "table", level: 1,
    q: "Using Table 2.5, a silt loam sample is powdery dry, slightly crusted but easily broken down. What is its condition?",
    opts: ["Wilting point, 0 available water remaining","Field capacity, all available water remaining","One-quarter of the available water remaining","Half of the available water remaining"], a: 0,
    why: "Powdery dry for loam and silt loam is the 0 row, the wilting point. At 0.25 it is somewhat crumbly but holds together from pressure.",
    eq: null, calc: null, fig: null, table: "2.5" },
  { id: "2-119", ch: 2, sec: "2.10", page: 25, type: "table", level: 3,
    q: "A silt loam (AWC 0.18 in/in) forms a ball that is somewhat plastic and sometimes slicks slightly. Using Table 2.5, about how much water is needed to refill a 3-ft root zone?",
    opts: ["6.48 in","4.86 in","1.62 in","3.24 in"], a: 3,
    why: "That description is fr = 0.50, so fd = 1 − fr = 0.50 (Eq. 2.11b). SWD = 0.50 × 0.18 × 36 = 3.24 in. 6.48 in is the whole TAW, and 4.86 in assumes fr = 0.25.",
    eq: "2.11b", calc: "eq-2.12", fig: null, table: "2.5" },
  { id: "2-120", ch: 2, sec: "2.10", page: 25, type: "table", level: 3,
    q: "In Table 2.5, why is the feel method weak for judging a loamy sand between 0.25 and 0.50 available water remaining?",
    opts: ["Loamy sand has no available water at 0.50","Loamy sand always ribbons out at both levels","Both levels read 'appears to be dry, will not form a ball with pressure'","The table does not include loamy sand"], a: 2,
    why: "The loamy sand or sand descriptions for 0.25 and 0.50 are the same, so the feel cannot tell them apart. In sands, check with a sensor or a gravimetric sample.",
    eq: null, calc: null, fig: null, table: "2.5" },
  { id: "2-121", ch: 2, sec: "2.10", page: 25, type: "recall", level: 2,
    q: "What accuracy does the book say experienced users achieve with the feel and appearance method?",
    opts: ["About ±0.01 in the fraction remaining","About ±0.10 in the fraction remaining","About ±1% in volumetric water content","About ±0.30 in the fraction remaining"], a: 1,
    why: "Experienced users reach about fr ± 0.10. So an estimate of 0.55 likely means a true value of 0.45 to 0.65. ±1% is the accuracy of a neutron probe.",
    eq: null, calc: null, fig: null, table: null },
  { id: "2-122", ch: 2, sec: "2.10", page: 25, type: "concept", level: 2,
    q: "Given its limited accuracy, why can the feel and appearance method still be adequate for irrigation management?",
    opts: ["It measures soil water tension directly","It is more accurate than any sensor in clay soils","It is cheap and quick at many locations, which matters given field variability","It needs no experience to use well"], a: 2,
    why: "Because soil water varies so much across a field, many quick, low-cost readings can be as useful as a few precise ones, especially if checked periodically against a more accurate method. It does require experience.",
    eq: null, calc: null, fig: null, table: null },
  { id: "2-123", ch: 2, sec: "2.10", page: 25, type: "recall", level: 1,
    q: "In a neutron probe, what slows the fast neutrons so that the count relates to water content?",
    opts: ["Hydrogen in soil water","Air in the soil pores","Dissolved salts in the soil water","Clay particles in the soil"], a: 0,
    why: "Fast neutrons are slowed mainly by hydrogen, and most hydrogen in soil is in water. The detector counts slow neutrons, which correlate well with θv.",
    eq: null, calc: null, fig: null, table: null },
  { id: "2-124", ch: 2, sec: "2.10", page: 26, type: "recall", level: 2,
    q: "What soil volume does a neutron probe sense, and how accurate is it?",
    opts: ["A sphere 2 to 3 ft across, within 10%","A sphere 6 to 10 in across, within 1%","The top 10 to 25 cm of soil, within 5%","A cylinder about 1.5 times the rod spacing, within 2%"], a: 1,
    why: "The neutron probe samples a sphere 6 to 10 in in diameter, depending on wetness, and is accurate within 1%. The cylinder description and 2% belong to TDR, and 10 to 25 cm is the remote sensing depth.",
    eq: null, calc: null, fig: null, table: null },
  { id: "2-125", ch: 2, sec: "2.10", page: 26, type: "figure", level: 2,
    q: "Figure 2.15 shows the neutron probe's sphere of influence at two depths. How does the sphere in dry soil compare with that in wet soil?",
    opts: ["Larger in wet soil","Zero in dry soil","The same size at all water contents","Larger in dry soil"], a: 3,
    why: "The radius rd in dry soil is drawn larger than rw in wet soil. With less hydrogen to slow them, neutrons travel farther before slowing.",
    eq: null, calc: null, fig: "2.15", table: null },
  { id: "2-126", ch: 2, sec: "2.10", page: 26, type: "concept", level: 2,
    q: "Which is a disadvantage of the neutron probe listed in the book?",
    opts: ["It cannot measure below 6 in","It needs a license and a calibration for the soil and access tube material","It only measures soil water tension","It must be dug up and reinstalled for each reading"], a: 1,
    why: "The probe is radioactive (licensed), costly, and needs calibration for the tube material (aluminum, steel or PVC) and soil. It is unreliable in the top 6 to 8 in, not below it.",
    eq: null, calc: null, fig: null, table: null },
  { id: "2-127", ch: 2, sec: "2.10", page: 26, type: "calc", level: 2,
    q: "Using the calibration in Figure 2.16, θv = 0.424 Cr − 0.03, what is the volumetric water content for a count ratio of 0.70?",
    opts: ["0.27","0.30","0.24","0.33"], a: 0,
    why: "θv = 0.424 × 0.70 − 0.03 = 0.297 − 0.03 = 0.267, about 0.27. 0.30 forgets the −0.03 intercept, and 0.24 subtracts it twice.",
    eq: null, calc: null, fig: "2.16", table: null },
  { id: "2-128", ch: 2, sec: "2.10", page: 26, type: "calc", level: 3,
    q: "With the Figure 2.16 calibration (θv = 0.424 Cr − 0.03), the average count ratio was 0.55 before an irrigation and 0.85 after. How much water was added to the top 1 ft?",
    opts: ["0.13 in","4.0 in","3.6 in","1.5 in"], a: 3,
    why: "Δθv = 0.424 × (0.85 − 0.55) = 0.127. Water added = 0.127 × 12 in = 1.5 in. 0.13 forgets to multiply by depth, and 3.6 in uses the count ratio change as if it were θv (0.30 × 12).",
    eq: null, calc: null, fig: "2.16", table: null },
  { id: "2-129", ch: 2, sec: "2.10", page: 26, type: "figure", level: 3,
    q: "Reading Figure 2.16, about what count ratio corresponds to a volumetric water content of 0.30?",
    opts: ["About 0.30","About 0.95","About 0.64","About 0.78"], a: 3,
    why: "Solve 0.30 = 0.424 Cr − 0.03: Cr = 0.33 / 0.424 = 0.78. The line passes θv = 0.30 near Cr = 0.78 on the plot. Reading Cr = θv (0.30) ignores the calibration.",
    eq: null, calc: null, fig: "2.16", table: null },
  { id: "2-130", ch: 2, sec: "2.10", page: 26, type: "concept", level: 3,
    q: "How does time domain reflectometry (TDR) sense water content?",
    opts: ["A pulse travels slower in wetter soil because water raises the apparent permittivity","A pulse travels faster in wetter soil because water lowers the permittivity","Current flow between rods rises with soil salinity","Neutrons are slowed by hydrogen near the rods"], a: 0,
    why: "Water dominates the soil's apparent dielectric permittivity εa. Wetter soil has higher εa, so the wave travels slower and the travel time is longer. TDR is accurate within about 2% and needs no radioactive license.",
    eq: null, calc: null, fig: null, table: null },
  { id: "2-131", ch: 2, sec: "2.10", page: 27, type: "concept", level: 2,
    q: "Capacitance probes can be installed in access tubes to read many depths. What is the tradeoff of the access-tube form?",
    opts: ["It measures soil water tension instead of θv","It cannot be calibrated for a specific soil","It requires a radioactive license","A much smaller sensing volume, because the sensor is not in direct soil contact"], a: 3,
    why: "Sensing through a tube wall reduces the volume measured. Capacitance probes also depend heavily on a soil-specific calibration for accurate θv, though they track trends well.",
    eq: null, calc: null, fig: null, table: null },
  { id: "2-132", ch: 2, sec: "2.10", page: 27, type: "figure", level: 1,
    q: "In Figure 2.17, which part of the tensiometer must be in close contact with the soil at the measurement depth?",
    opts: ["The reservoir","The upper end of the tube","The vacuum gauge","The ceramic tip"], a: 3,
    why: "The porous ceramic tip connects the water in the tube hydraulically with soil water. As the soil dries, water is pulled out through the tip and the gauge shows the vacuum.",
    eq: null, calc: null, fig: "2.17", table: null },
  { id: "2-133", ch: 2, sec: "2.10", page: 27, type: "recall", level: 1,
    q: "What is the practical operating range of a tensiometer?",
    opts: ["5 to 200 cb","0 to 75 cb","50 to 1,500 cb","0 to 1,500 cb"], a: 1,
    why: "Gauges read 0 to 100 cb, but near 1 bar dissolved air comes out, so the practical range is 0 to 75 cb. 5 to 200 cb is the granular matrix sensor range.",
    eq: null, calc: null, fig: null, table: null },
  { id: "2-134", ch: 2, sec: "2.10", page: 27, type: "concept", level: 2,
    q: "Why do tensiometer readings become unreliable as tension approaches 1 bar?",
    opts: ["Dissolved air comes out of the water and collects in the tube","Soil water freezes at that tension","The ceramic cup cracks at that tension","The gauge spring is not rated above 75 cb"], a: 0,
    why: "As the vacuum approaches 1 bar, dissolved air is released and accumulates at the top of the tube, breaking the reading. That is why the working range is 0 to 75 cb.",
    eq: null, calc: null, fig: null, table: null },
  { id: "2-135", ch: 2, sec: "2.10", page: 28, type: "recall", level: 2,
    q: "What are the usable tension ranges of gypsum blocks and granular matrix sensors?",
    opts: ["Gypsum above about 50 cb, granular matrix 5 to 200 cb","Gypsum 0 to 75 cb, granular matrix 75 to 1,500 cb","Gypsum 5 to 200 cb, granular matrix above 50 cb","Both 0 to 75 cb"], a: 0,
    why: "Fine gypsum only responds at high tensions, usually above 50 cb. The coarser granular matrix sensors work from 5 to 200 cb and last longer.",
    eq: null, calc: null, fig: null, table: null },
  { id: "2-136", ch: 2, sec: "2.10", page: 28, type: "concept", level: 3,
    q: "Why can a granular matrix sensor reading represent a larger soil volume than a small θv sensor?",
    opts: ["Granular matrix sensors average the whole root zone electrically","At small scales, matric potential varies less in space than θv does","Matric potential does not depend on soil texture","The sensor body is several feet long"], a: 1,
    why: "On a cm to m scale, spatial variability in ψm is lower than in θv, so a tension reading may represent more soil. Converting it to θv, however, needs a release curve and adds uncertainty.",
    eq: null, calc: null, fig: null, table: null },
  { id: "2-137", ch: 2, sec: "2.10", page: 28, type: "recall", level: 2,
    q: "What are the drawbacks of thermal dissipation blocks?",
    opts: ["They only work above 1,500 cb","They respond only to soil salinity","They require a radioactive license","Each must be individually calibrated, and they cost much more than granular matrix sensors"], a: 3,
    why: "Heat dissipation blocks are sensitive over a wide range but need individual calibration and are considerably more expensive than granular matrix sensors.",
    eq: null, calc: null, fig: null, table: null },
  { id: "2-138", ch: 2, sec: "2.10", page: 29, type: "recall", level: 1,
    q: "How many depths does the book say should be measured to represent root zone soil water?",
    opts: ["One, near the surface where roots start","At least six, every 6 inches","At least two, and often three or four","One, at the depth of most roots"], a: 2,
    why: "A minimum of two depths is needed, and three or four are often required to represent the root zone. A boot-heel check of the surface is inadequate.",
    eq: null, calc: null, fig: null, table: null },
  { id: "2-139", ch: 2, sec: "2.10", page: 29, type: "concept", level: 2,
    q: "The book suggests a way to reduce uncertainty in soil water sensor data. What is it?",
    opts: ["Focus on trends, find FC from the sensor after a big wetting event, and track depletion","Replace sensors every month to keep readings fresh","Use only the first reading after installation","Average all depths into one number before looking at it"], a: 0,
    why: "Trends are more reliable than absolute values. Reading the sensor's own FC after a profile-wetting event and tracking SWD below it removes much of the calibration error.",
    eq: null, calc: null, fig: null, table: null },
  { id: "2-140", ch: 2, sec: "2.10", page: 29, type: "recall", level: 2,
    q: "Which satellites does the book name as producing soil water data products, and from which agencies?",
    opts: ["SMOS from NASA and SMAP from the European Space Agency","SMAP from NASA and SMOS from the European Space Agency","Landsat from NASA and Sentinel from the European Space Agency","GOES from NOAA and MODIS from the European Space Agency"], a: 1,
    why: "SMAP (Soil Moisture Active Passive) is a NASA satellite and SMOS (Soil Moisture and Ocean Salinity) is from the European Space Agency.",
    eq: null, calc: null, fig: null, table: null },
  { id: "2-141", ch: 2, sec: "2.10", page: 25, type: "scenario", level: 2,
    q: "A grower dried soil samples in a microwave and says, 'One sample smoked and came out showing way more water than the others.' What went wrong?",
    opts: ["Smoke means the sample was saturated when collected","The microwave did not remove all the water","Once the water was gone the sample overheated and burned organic matter, counted as water","Microwaves cannot dry soil at all"], a: 2,
    why: "After moisture is driven off, sample temperature rises fast. Burning organic matter loses mass that is mistaken for water, so θm is overestimated. Typical drying time is 10 to 30 minutes.",
    eq: null, calc: null, fig: null, table: null },
  { id: "2-142", ch: 2, sec: "2.10", page: 27, type: "scenario", level: 3,
    q: "A grower uses tensiometers in a silty clay loam and plans to irrigate at 50% depletion. They read 70 cb and the crop looks fine. What do you tell him?",
    opts: ["Tensiometers top out near 75 cb, so on fine soils they may not reach the 50% trigger, so use another sensor","70 cb is the wilting point for silty clay loam","Tensiometers read best above 75 cb in clays","70 cb means the soil is near saturation, so wait"], a: 0,
    why: "In finer soils, 50% depletion can occur at tensions beyond the tensiometer's 0 to 75 cb range (silt loam is only about 45% depleted at 75 cb). A granular matrix sensor (5 to 200 cb) or a θv sensor fits better.",
    eq: null, calc: null, fig: null, table: null },
  { id: "2-143", ch: 2, sec: "2.10", page: 28, type: "scenario", level: 3,
    q: "A grower with gypsum blocks in a saline field says they always read wetter than the crop looks. What is the likely cause?",
    opts: ["Gypsum blocks overestimate tension in all soils","Saline soils hold more available water","The blocks are reading osmotic potential correctly","Salts lower electrical resistance, so the blocks read wetter than the true tension"], a: 3,
    why: "Resistance depends on both water and dissolved salts. Gypsum partly buffers salts, but in saline soils salts still lower resistance, giving inaccurate matric potential. The crop also faces osmotic stress the block does not show.",
    eq: null, calc: null, fig: null, table: null },
  { id: "2-144", ch: 2, sec: "2.10", page: 27, type: "scenario", level: 3,
    q: "A grower installs a capacitance probe in sandy soil. It reads θv = 0.40 a day after a heavy irrigation. He asks if that is real. What do you advise?",
    opts: ["It is accurate, since capacitance probes need no calibration","Likely a calibration issue, so use trends and take the post-drainage reading as his field capacity","The soil is saturated, so stop irrigating for a month","Replace it with a tensiometer, which reads θv directly"], a: 1,
    why: "Capacitance probes track trends well, but absolute θv depends on a soil-specific calibration. A sand at FC is nearer 0.15. Setting FC from the sensor's own reading after drainage and tracking depletion avoids the calibration error.",
    eq: null, calc: null, fig: null, table: null },
  { id: "2-145", ch: 2, sec: "2.10", page: 29, type: "scenario", level: 1,
    q: "A grower wants one soil moisture sensor at 6 inches in his corn because 'that is where it dries first.' What is the book's advice?",
    opts: ["Use a boot heel check instead of sensors","One shallow sensor is enough if it is read daily","Place one sensor below the root zone only","Measure at depths that represent the root zone, at least two and often three or four"], a: 3,
    why: "Soil water must be measured at depths that represent the root zone. A single shallow reading, like a boot heel test, misses what is happening in the deeper roots.",
    eq: null, calc: null, fig: null, table: null },
  { id: "2-146", ch: 2, sec: "2.10", page: 25, type: "scenario", level: 2,
    q: "A grower using the feel method estimates 0.55 of the available water remaining. He asks how much he can trust it. What do you tell him?",
    opts: ["The feel method cannot estimate fraction remaining","It is within ±0.01 if done carefully","Experienced users are within about ±0.10, so it is likely 0.45 to 0.65","It is exact if he formed a ball"], a: 2,
    why: "The book cites accuracy of about ±0.10 for experienced users. Checking periodically against a more accurate method improves confidence.",
    eq: null, calc: null, fig: null, table: null },
  { id: "2-147", ch: 2, sec: "2.10", page: 29, type: "scenario", level: 2,
    q: "A grower asks whether he can schedule his corn (roots to 100 cm) from a satellite soil moisture map. What is the main limitation?",
    opts: ["Satellites sense only the top 10 to 25 cm, not the full root zone","Satellites measure only soil temperature","Satellite data are too coarse to show any field patterns","Satellites measure soil water tension, not θv"], a: 0,
    why: "Remote sensing gives valuable spatial patterns, but it measures θv only in a shallow surface layer. For deep-rooted crops, root zone estimates need other data or models.",
    eq: null, calc: null, fig: null, table: null },
  { id: "2-148", ch: 2, sec: "2.10", page: 26, type: "scenario", level: 3,
    q: "A researcher's neutron probe readings at 6 inches are always lower than gravimetric samples, but deeper readings match. Why?",
    opts: ["The access tube is the wrong material at that depth","Hydrogen is absent near the surface","The probe reads tension, not θv, near the surface","Near the surface, neutrons escape to the air, so readings in the top 6 to 8 in need a separate calibration"], a: 3,
    why: "The book lists unreliable readings in the top 6 to 8 in as a neutron probe disadvantage, requiring a separate calibration. The sphere of influence extends above the soil surface there.",
    eq: null, calc: null, fig: null, table: null },
  { id: "2-149", ch: 2, sec: "2.10", page: 28, type: "scenario", level: 2,
    q: "A grower using granular matrix sensors asks if he must convert the readings to θv to schedule irrigation. What do you say?",
    opts: ["No, just irrigate whenever the reading is above zero","Yes, tension readings are useless without θv","No, compare tension directly with a crop stress threshold, which avoids release-curve errors","Yes, multiply cb by 0.01 to get θv"], a: 2,
    why: "Converting ψm to θv needs a soil water release curve and adds uncertainty. Scheduling with granular matrix sensors often uses ψm directly against a threshold where stress is expected.",
    eq: null, calc: null, fig: null, table: null },
  { id: "2-150", ch: 2, sec: "2.11", page: 30, type: "recall", level: 1,
    q: "According to the chapter summary, what is the typical range of available water capacity across soils?",
    opts: ["1 to 3 inches per inch","0.01 to 0.05 inches per inch","0.25 to 0.50 inches per inch","0.05 to 0.25 inches per inch"], a: 3,
    why: "AWC ranges from about 0.05 in/in in coarse sands to about 0.25 in/in. Values near 0.30 to 0.50 are water contents at field capacity or saturation, not AWC.",
    eq: null, calc: null, fig: null, table: null }
]);
